#!/usr/bin/env python3
"""Offline atomic HTTP/3 -> HTTP/1.1 bridge fixture translator.

Reads one JSON scenario from stdin and writes the audit ledger as one JSON
object on stdout.  Diagnostics (if any) go to stderr only.

Octet convention: every string in a header field pair and in the output ledger
denotes octets, where Unicode code points U+0000..U+00FF map to the single byte
with that value; i.e. latin-1 is the octet codec.  JSON transport is UTF-8.

No sockets, no child processes, no filesystem writes: pure translation.
"""

import json
import sys
from ipaddress import IPv6Address

MAX_CONTENT = 65536          # bytes of concatenated DATA per stream
MAX_SECTION_SIZE = 8192      # uncompressed HEADERS section size per section

# --- octet classes -------------------------------------------------------

_TCHAR = "abcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-.^_`|~"
NAME_OCTETS = frozenset(_TCHAR.encode('ascii'))

_VISIBLE = frozenset(range(0x21, 0x7F)) | frozenset(range(0x80, 0x100))
_INNER = _VISIBLE | {0x20, 0x09}

_ASCII_DIGITS = frozenset(b'0123456789')
_HEX_DIGITS = frozenset(b'0123456789abcdefABCDEF')
_PATH_OCTETS = frozenset(
    ("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
     "-._~!$&'()*+,;=:@/?").encode('ascii'))
_DNS_OCTETS = frozenset(
    ("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-").encode('ascii'))
_ALNUM_OCTETS = frozenset(
    ("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789").encode('ascii'))
_DNS_CHARS = frozenset(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")
_DIGIT_CHARS = frozenset("0123456789")

# --- protocol / policy constants -----------------------------------------

_PSEUDO_ALLOWED = frozenset((b':method', b':scheme', b':authority', b':path'))
_PSEUDO_REQUIRED = (b':method', b':scheme', b':path')
_METHODS = frozenset((b'GET', b'HEAD', b'POST', b'PUT', b'PATCH', b'DELETE',
                      b'OPTIONS'))
_SCHEME_DEFAULT_PORT = {'http': 80, 'https': 443}

_PROHIBITED = frozenset((b'connection', b'proxy-connection', b'keep-alive',
                         b'transfer-encoding', b'upgrade', b'http2-settings',
                         b'trailer'))
_REPEATABLE = frozenset((b'accept', b'accept-encoding', b'cache-control',
                         b'if-match', b'if-none-match', b'pragma', b'vary'))
_XLIST = b'x-list-'
_XAUDIT = b'x-audit-'
_HOST = b'host'
_COOKIE = b'cookie'
_TE = b'te'
_CONTENT_LENGTH = b'content-length'
_TRAILER_VALUES = b'trailers'


def octets(value):
    """Return the octet string denoted by *value*, or None if not denotable."""
    if not isinstance(value, str):
        return None
    try:
        return value.encode('latin-1')
    except UnicodeEncodeError:
        return None


def valid_field_name(name):
    return bool(name) and not (set(name) - NAME_OCTETS)


def valid_field_value(value):
    if not value:
        return True
    if value[0] not in _VISIBLE or value[-1] not in _VISIBLE:
        return False
    return not (set(value) - _INNER)


def valid_origin_form(path):
    """Origin-form target: '/...', never '//', allowed octets and %HH only."""
    if not path.startswith(b'/') or path.startswith(b'//'):
        return False
    index = 0
    length = len(path)
    while index < length:
        octet = path[index]
        if octet == 0x25:  # '%'
            if index + 2 >= length:
                return False
            if path[index + 1] not in _HEX_DIGITS or path[index + 2] not in _HEX_DIGITS:
                return False
            index += 3
            continue
        if octet not in _PATH_OCTETS:
            return False
        index += 1
    return True


def canonical_dns_or_ipv4(host):
    """Canonicalise a non-bracketed host; return None when invalid."""
    if not host or len(host) > 253:
        return None
    labels = host.split('.')
    for label in labels:
        if not label or len(label) > 63:
            return None
        if set(label) - _DNS_CHARS:
            return None
        if label[0] not in _ALNUM_CH or label[-1] not in _ALNUM_CH:
            return None
    if len(labels) == 4 and all(not (set(label) - _DIGIT_CHARS) for label in labels):
        # Four all-digit labels: it must be a strict IPv4 literal instead.
        parts = []
        for label in labels:
            if len(label) > 1 and label[0] == '0':
                return None
            if int(label) > 255:
                return None
            parts.append(label)
        return '.'.join(parts)
    return host.lower()


_ALNUM_CH = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")


def canonical_authority(value, scheme):
    """Return the canonical authority octet-string, or None when invalid."""
    if not value:
        return None
    default_port = _SCHEME_DEFAULT_PORT[scheme]
    if value.startswith('['):
        close = value.find(']')
        if close < 0:
            return None
        inner = value[1:close]
        rest = value[close + 1:]
        if rest and not rest.startswith(':'):
            return None
        port = rest[1:] if rest else None
        if not inner or '%' in inner or '[' in inner or ']' in inner:
            return None
        try:
            host = '[' + IPv6Address(inner).compressed + ']'
        except (ValueError, TypeError):
            return None
    else:
        if '[' in value or ']' in value:
            return None
        pieces = value.split(':')
        if len(pieces) > 2:
            return None
        host = canonical_dns_or_ipv4(pieces[0])
        if host is None:
            return None
        port = pieces[1] if len(pieces) == 2 else None
    if port is not None:
        if not 1 <= len(port) <= 5 or set(port) - _DIGIT_CHARS:
            return None
        number = int(port)
        if number < 1 or number > 65535:
            return None
        if number != default_port:
            host += ':' + str(number)
    return host


def section_size_ok(fields):
    total = 0
    for name, value in fields:
        if name is None or value is None:
            return False
        total += len(name) + len(value) + 32
        if total > MAX_SECTION_SIZE:
            return False
    return True


def content_length_ok(lines, body_length):
    """All members of all lines denote one integer equal to *body_length*."""
    canonical = None
    for line in lines:
        for member in line.split(b','):
            member = member.strip(b' \t')
            if not member or (set(member) - _ASCII_DIGITS):
                return False
            stripped = member.lstrip(b'0') or b'0'
            if canonical is None:
                canonical = stripped
            elif stripped != canonical:
                return False
    if canonical is None:
        return True
    # Compare decimal text; never route huge numerals through int()/float.
    return canonical == str(body_length).encode('ascii')


def build_request(initial, trailing, body, routes):
    """Validate a FIN-complete stream; return (raw, origin, cache_key) or None."""
    if not section_size_ok(initial):
        return None
    if trailing is not None and not section_size_ok(trailing):
        return None

    pseudo = {}
    regular = []
    saw_regular = False
    for name, value in initial:
        if name is None or value is None:
            return None
        if name.startswith(b':'):
            if saw_regular or name in pseudo or name not in _PSEUDO_ALLOWED:
                return None
            if not valid_field_value(value):
                return None
            pseudo[name] = value
        else:
            saw_regular = True
            if not valid_field_name(name) or not valid_field_value(value):
                return None
            regular.append((name, value))

    for required in _PSEUDO_REQUIRED:
        if required not in pseudo:
            return None

    method = pseudo[b':method']
    if method not in _METHODS:
        return None
    scheme_bytes = pseudo[b':scheme']
    scheme = scheme_bytes.decode('ascii') if set(scheme_bytes) - set() else ''
    if scheme not in _SCHEME_DEFAULT_PORT:
        return None
    path = pseudo[b':path']
    if path == b'*':
        if method != b'OPTIONS':
            return None
    elif not valid_origin_form(path):
        return None

    # --- authority: :authority and/or a single host line -------------------
    authority = pseudo.get(b':authority')
    host_lines = [value for name, value in regular if name == _HOST]
    if len(host_lines) > 1:
        return None
    host_value = host_lines[0] if host_lines else None
    if authority is not None:
        if not authority:
            return None
        if host_value is not None and host_value != authority:
            return None
        chosen = authority
    elif host_value is not None:
        if not host_value:
            return None
        chosen = host_value
    else:
        return None
    canonical = canonical_authority(chosen.decode('latin-1'), scheme)
    if canonical is None:
        return None
    origin = routes.get(scheme + '://' + canonical)
    if origin is None:
        return None

    # --- initial regular fields -------------------------------------------
    emitted = []
    cookie_values = []
    cookie_slot = -1
    length_lines = []
    seen = set()
    for name, value in regular:
        if name in _PROHIBITED:
            return None
        if name == _HOST:
            continue  # replaced by the canonical host line
        if name == _TE:
            if name in seen or value != _TRAILER_VALUES:
                return None
            seen.add(name)
            continue  # consumed, never forwarded
        if name == _CONTENT_LENGTH:
            length_lines.append(value)
            continue  # reframed by the bridge
        if name == _COOKIE:
            if cookie_slot < 0:
                cookie_slot = len(emitted)
                emitted.append((name, b''))
            cookie_values.append(value)
            continue
        if name in seen:
            if name not in _REPEATABLE and not (
                    name.startswith(_XLIST) and len(name) > len(_XLIST)):
                return None
        seen.add(name)
        emitted.append((name, value))

    if not content_length_ok(length_lines, len(body)):
        return None
    if cookie_slot >= 0:
        emitted[cookie_slot] = (_COOKIE, b'; '.join(cookie_values))

    # --- trailers ----------------------------------------------------------
    trailer_pairs = []
    trailer_names = []
    announced = set()
    if trailing is not None:
        for name, value in trailing:
            if name is None or value is None:
                return None
            if not valid_field_name(name) or not valid_field_value(value):
                return None
            if not name.startswith(_XAUDIT) or len(name) == len(_XAUDIT):
                return None
            trailer_pairs.append((name, value))
            if name not in announced:
                announced.add(name)
                trailer_names.append(name)

    # --- canonical HTTP/1.1 serialization ---------------------------------
    out = bytearray()
    out += method + b' ' + path + b' HTTP/1.1\r\n'
    out += b'host: ' + canonical.encode('latin-1') + b'\r\n'
    for name, value in emitted:
        out += name + b': ' + value + b'\r\n'
    if trailing is None:
        out += b'content-length: ' + str(len(body)).encode('ascii') + b'\r\n\r\n'
        out += body
    else:
        out += b'transfer-encoding: chunked\r\n'
        if trailer_names:
            out += b'trailer: ' + b', '.join(trailer_names) + b'\r\n'
        out += b'\r\n'
        if body:
            out += ('%x' % len(body)).encode('ascii') + b'\r\n' + body + b'\r\n'
        out += b'0\r\n'
        for name, value in trailer_pairs:
            out += name + b': ' + value + b'\r\n'
        out += b'\r\n'

    cache_key = [method.decode('ascii'), scheme, canonical, path.decode('latin-1')]
    return bytes(out), origin, cache_key


def blank_record(sid, status):
    return {'sid': sid, 'status': status, 'commit_at': None, 'origin': None,
            'offset': None, 'length': 0, 'cache_key': None}


def new_state():
    return {'phase': 0, 'initial': None, 'trailing': None, 'body': bytearray(),
            'too_long': False, 'struct_bad': False, 'terminal': None,
            'record': None}


def bridge(scenario):
    routes = scenario['routes']
    pipelines = {}
    for label in routes.values():
        pipelines.setdefault(label, bytearray())

    states = {}
    for index, event in enumerate(scenario['events']):
        sid = event['sid']
        state = states.get(sid)
        if state is None:
            state = new_state()
            states[sid] = state
        kind = event['type']
        if state['record'] is not None:
            continue  # terminal event was this stream's last event
        if kind == 'headers':
            fields = [(octets(pair[0]), octets(pair[1])) for pair in event['fields']]
            phase = state['phase']
            if phase == 0:
                state['phase'] = 1
                state['initial'] = fields
            elif phase == 1:
                state['phase'] = 2
                state['trailing'] = fields
            else:
                state['struct_bad'] = True
        elif kind == 'data':
            if state['phase'] != 1:
                state['struct_bad'] = True
            elif not state['too_long']:
                try:
                    payload = bytes.fromhex(event['hex'])
                except (ValueError, TypeError, AttributeError):
                    state['struct_bad'] = True
                    payload = b''
                if len(state['body']) + len(payload) > MAX_CONTENT:
                    state['too_long'] = True
                else:
                    state['body'].extend(payload)
        elif kind == 'unknown':
            pass  # opaque frames are ignored everywhere before the terminal
        elif kind == 'reset':
            state['terminal'] = 'reset'
            state['record'] = blank_record(sid, 'cancelled')
        elif kind == 'fin':
            state['terminal'] = 'fin'
            record = None
            if not state['struct_bad'] and state['phase'] >= 1 and not state['too_long']:
                try:
                    built = build_request(state['initial'], state['trailing'],
                                          state['body'], routes)
                except Exception:  # pragma: no cover - defensive
                    built = None
                if built is not None:
                    raw, origin, cache_key = built
                    pipeline = pipelines[origin]
                    record = {'sid': sid, 'status': 'forwarded', 'commit_at': index,
                              'origin': origin, 'offset': len(pipeline),
                              'length': len(raw), 'cache_key': cache_key}
                    pipeline.extend(raw)
            state['record'] = record if record is not None else blank_record(sid, 'rejected')
        else:
            state['struct_bad'] = True

    streams = []
    for sid in sorted(states):
        record = states[sid]['record']
        streams.append(record if record is not None else blank_record(sid, 'incomplete'))
    return {'streams': streams,
            'origins': {label: pipeline.hex() for label, pipeline in pipelines.items()}}


def main():
    scenario = json.loads(sys.stdin.buffer.read())
    json.dump(bridge(scenario), sys.stdout, ensure_ascii=True)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
